def factorize(n):
    factors = []
    while n > 1:
        for i in range(2, int(n**0.5) + 2):
            while n % i == 0:
                factors.append(str(i))
                n //= i
        if n > 1 and n != 2:
            factors.append('prime')
    return factors, len(factors)

