def allocate_workspace(n):
    if not isinstance(n, int) or n <= 0:
        return "Invalid input"
    c_n = ctypes.c_int(n)
    workspace_ptr = ctypes.POINTER(ctypes.c_void_p)(ctypes.byref(ctypes.c_void_p()))
    ret_code = gslcblas.gsl_integration_workspace_alloc.restype(c_int)(ctypes.cast(c_int, workspace_ptr), c_n)
    if ret_code != 0:
        return "Failed to allocate workspace"
    workspace = workspace_ptr.contents.value
    return workspace

def free_workspace(workspace):
    if not isinstance(workspace, int):
        return "Invalid input"
    ret_code = gslcblas.gsl_integration_workspace_free.restype(c_int)(ctypes.cast(c_int, workspace))
    if ret_code != 0:
        return "Failed to free workspace"
    return "Successfully freed workspace"

