libgsl.linalg_LQ_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]

def lq_decomposition(matrix):
    # Convert the input matrix to a numpy array and then to a ctypes array
    matrix_array = np.array(matrix, dtype=np.double)
    c_matrix = matrix_array.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    # Create an output tau vector with the appropriate size and set it to zero
    tau = [0] * (len(matrix) - 1)
    tau_array = (ctypes.c_double * len(tau))(tuple(tau))

    # Perform LQ decomposition
    success = libgsl.linalg_LQ_decomp(c_matrix, tau_array)

    # Check for successful decomposition
    if success != 0:
        return json.dumps(
            {
                "error": "LQ decomposition failed"
            }
        )

    # Convert the decomposed matrix and tau vector to lists and return as JSON
    decomposed_matrix = matrix_array.tolist()
    return json.dumps(
        {
            "Candidate_solution": ",".join([str(decomposed_matrix), str(tau)])
        }
    )

