import numpy as np

def cholesky_decomposition(matrix):
    m = int(np.sqrt(len(matrix)))
    P = gsl_permutation_alloc(m)
    A = [gsl_matrix_alloc(m, m) for _ in range(2)]

    for i in range(m):
        for j in range(i, m):
            A[0].gsl_matrix_set(A[0], i, j, matrix[i][j])
            if i == j:
                c = 1.0
                for k in range(i - 1):
                    c -= A[0].gsl_matrix_get(A[0], i, k) * A[0].gsl_matrix_get(A[0], j, k)
                    c /= A[0].gsl_matrix_get(A[0], i, k)
                for k in range(i):
                    A[1].gsl_matrix_set(A[1], k, j, A[0].gsl_matrix_get(A[0], k, j))
                    A[0].gsl_matrix_set(A[0], i, j, c * A[0].gsl_matrix_get(A[0], i, j) - A[1].gsl_matrix_get(A[1], k, j) * A[1].gsl_matrix_get(A[1], k, j))
            else:
                for k in range(i):
                    c = matrix[i][j] - A[0].gsl_matrix_get(A[0], i, k) * A[0].gsl_matrix_get(A[0], j, k)
                    if k >= i:
                        c /= A[0].gsl_matrix_get(A[0], i, i)
                        A[1].gsl_matrix_set(A[1], k, j, c)
    return matrix.copy(), [gsl_permutation_get(P, i) for i in range(m)]

